create extension if not exists btree_gist;
create type public.app_role as enum ('admin','staff');
create type public.appointment_status as enum ('pending','confirmed','completed','cancelled','no_show');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,full_name text,role app_role not null default 'staff',created_at timestamptz default now());
create table public.services(id uuid primary key default gen_random_uuid(),name text not null unique,description text,price numeric(10,2) not null check(price>=0),duration_minutes int not null check(duration_minutes>0),buffer_minutes int not null default 0,is_active boolean default true,is_bookable boolean default true,sort_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.appointments(id uuid primary key default gen_random_uuid(),customer_name text not null,customer_phone text not null,customer_note text,service_id uuid not null references public.services(id),appointment_date date not null,start_time time not null,end_time time not null,status appointment_status not null default 'pending',internal_note text,created_at timestamptz default now(),updated_at timestamptz default now(),check(end_time>start_time));
create table public.business_hours(id bigint generated by default as identity primary key,day_of_week int unique not null check(day_of_week between 0 and 6),is_open boolean default true,opening_time time,closing_time time,break_start time,break_end time,slot_interval_minutes int default 30,updated_at timestamptz default now());
create table public.blocked_times(id uuid primary key default gen_random_uuid(),blocked_date date not null,start_time time,end_time time,is_full_day boolean default false,reason text,created_at timestamptz default now());
create table public.gallery_images(id uuid primary key default gen_random_uuid(),image_url text not null,alt_text text not null,sort_order int default 0,is_active boolean default true,is_featured boolean default false,created_at timestamptz default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),customer_name text not null,review_text text not null,rating int check(rating between 1 and 5),is_active boolean default true,sort_order int default 0,created_at timestamptz default now());
create table public.business_settings(id int primary key default 1 check(id=1),business_name text not null,slogan text,phone text,whatsapp text,address text,instagram_url text,waze_url text,hero_title text,hero_text text,hero_image_url text,about_title text,about_text text,updated_at timestamptz default now());
alter table public.appointments add constraint no_overlapping_appointments exclude using gist (appointment_date with =,tsrange((appointment_date+start_time)::timestamp,(appointment_date+end_time)::timestamp,'[)') with &&) where (status not in ('cancelled'));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role in ('admin','staff'))$$;
alter table public.profiles enable row level security;alter table public.services enable row level security;alter table public.appointments enable row level security;alter table public.business_hours enable row level security;alter table public.blocked_times enable row level security;alter table public.gallery_images enable row level security;alter table public.reviews enable row level security;alter table public.business_settings enable row level security;
create policy "public reads active services" on public.services for select using(is_active=true);create policy "public reads hours" on public.business_hours for select using(true);create policy "public reads active gallery" on public.gallery_images for select using(is_active=true);create policy "public reads active reviews" on public.reviews for select using(is_active=true);create policy "public reads settings" on public.business_settings for select using(true);
create policy "staff profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin());create policy "staff services" on public.services for all using(public.is_admin()) with check(public.is_admin());create policy "staff appointments" on public.appointments for all using(public.is_admin()) with check(public.is_admin());create policy "staff hours" on public.business_hours for all using(public.is_admin()) with check(public.is_admin());create policy "staff blocks" on public.blocked_times for all using(public.is_admin()) with check(public.is_admin());create policy "staff gallery" on public.gallery_images for all using(public.is_admin()) with check(public.is_admin());create policy "staff reviews" on public.reviews for all using(public.is_admin()) with check(public.is_admin());create policy "staff settings" on public.business_settings for all using(public.is_admin()) with check(public.is_admin());
